mapper.sql:
WHERE gl.is_approve = 1 AND gl.is_active = 1 AND gld.employee_id IS NOT NULL
AND gld.company_id = #{filter.companyId}
AND gld.employee_id IN (SELECT employee_id FROM employee_egroups WHERE egroup_id = #{filter.groupId})
AND gld.employee_id = #{filter.employeeId}
AND gld.branch_id = #{filter.branchId}
AND gld.chart_account_id IN ( SELECT id FROM chart_accounts WHERE is_active = 1 AND chart_account_type_id IN ( SELECT id FROM chart_account_types WHERE name = 'Accounts Receivable' ) ) AND sales_order_id IS NULL AND credit_memo_id IS NULL AND purchase_order_id IS NULL AND purchase_return_id IS NULL AND debit > 0 AND debit-(IFNULL((SELECT IFNULL(SUM(credit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND company_id = gld.company_id AND employee_id = gld.employee_id), 0))>0.001

mapper.select:
SELECT



ORDER BY gl.`date` ASC

    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT



ORDER BY ar_agings.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT IFNULL(SUM(credit),0) AS credit, `main_gl_id` AS mainGlId, `chart_account_id` AS chartAccountId, `company_id` AS companyId, `employee_id` AS employeeId FROM general_ledgers gl2 INNER JOIN general_ledger_details gld2 ON gl2.id=gld2.general_ledger_id WHERE gl2.is_approve=1 AND gl2.is_active=1
AND company_id = #{filter.companyId}
AND employee_id IN ( SELECT employee_id FROM employee_egroups WHERE egroup_id= #{filter.groupId} )
AND employee_id = #{filter.employeeId}
AND chart_account_id IN (SELECT id FROM chart_accounts WHERE is_active=1 AND chart_account_type_id IN (SELECT id FROM chart_account_types WHERE name='Accounts Receivable')) AND sales_order_id IS NULL AND credit_memo_id IS NULL AND purchase_order_id IS NULL AND purchase_return_id IS NULL AND credit>0 GROUP BY `main_gl_id`, `chart_account_id`, `company_id`, `employee_id`
